            <p data-id="jr-stage-1" data-name="Stage" style={{ position: 'relative', order: '1', fontFamily: 'Work Sans, -apple-system, BlinkMacSystemFont, sans-serif', color: '#ffffff', fontSize: '13px', lineHeight: '1.3', fontWeight: '600', textAlign: 'center', backgroundColor: '#4358CD', borderRadius: '9999px', padding: '6px 10px 6px 10px' }}>Ask</p>
