          <p data-id="aff-1-5" data-name="Sticky" style={{ position: 'relative', flex: '0 0 auto', order: '6', fontFamily: 'Work Sans, -apple-system, BlinkMacSystemFont, sans-serif', color: '#2b2b2b', fontSize: '12px', lineHeight: '1.3', backgroundColor: '#FFF1B8', borderRadius: '4px', padding: '8px 9px 8px 9px', boxShadow: '0 1px 2px rgba(0,0,0,.08)' }}>Real # hashtags</p>
