        <div data-id="ref-2" data-name="Reference · Karakeep" style={{ position: 'relative', order: '1', display: 'flex', flexDirection: 'column', gap: '6px', padding: '16px 16px 16px 16px', borderRadius: '16px', boxShadow: '0 1px 2px rgba(20,27,77,.05), 0 8px 28px rgba(20,27,77,.08)', backgroundColor: '#ffffff' }}>
          <p data-id="ref-2-h" data-name="Name" style={{ position: 'relative', flex: '0 0 auto', order: '0', fontFamily: 'Work Sans, -apple-system, BlinkMacSystemFont, sans-serif', color: '#16191C', fontSize: '15px', lineHeight: '1.3', fontWeight: '600' }}>Karakeep</p>
          <p data-id="ref-2-t" data-name="Lesson" style={{ position: 'relative', flex: '0 0 auto', order: '1', fontFamily: 'Work Sans, -apple-system, BlinkMacSystemFont, sans-serif', color: '#2A2E33', fontSize: '13.5px', lineHeight: '1.45' }}>Agent APIs and tags are table stakes, so they can't be the difference</p>
        </div>
