          <div data-id="anatomy-img" data-name="Event card" data-pinned="true" style={{ position: 'absolute', left: '225px', top: '18px', width: '450px', borderRadius: '12px', aspectRatio: '900 / 786', backgroundImage: 'url(/assets/supafeed/crop-event-card.webp)', backgroundSize: 'cover', backgroundPosition: 'center', backgroundRepeat: 'no-repeat' }} aria-hidden="true" />
